const CACHE='atlasclock-v31';
const BASE=self.registration.scope;
const ASSETS=['./','./index.html','./app.js','./styles.css','./cities.json','./countries.json','./world.svg','./manifest.webmanifest','./assets/globe-atlas.svg','./assets/tokyo.svg','./assets/sydney.svg','./assets/los-angeles.svg','./assets/new-york.svg','./assets/london.svg','./assets/new-delhi.svg','./assets/globe-reference.png','./assets/map-reference.png','./assets/hourglass-reference-isolated.png','./assets/hourglass-reference-empty.png'].map(x=>new URL(x,BASE).pathname);
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(url.origin!==location.origin)return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(response=>response||caches.match(new URL('./index.html',BASE).pathname))));});
